export function sourceText(text){
  for(const dictionary of Object.values(dictionaries)){
    for(const [source,translated] of Object.entries(dictionary))if(translated===text)return source;
  }
  return text;
}

export function translate(text, language) {
  if(language==="es"||!language)return sourceText(text);
  const dictionary=dictionaries[language];
  if(!dictionary)return text;
  const source=sourceText(text);
  if(dictionary[source])return dictionary[source];
  return translateDynamic(source,dictionary,language);
}

function translateDynamic(text,dictionary,language){
  const rules=language==="qu"?[
    [/^Hola, (.+)\. ¿Qué trámite necesitas hoy\?$/,"Rimaykullayki, $1. ¿Ima ruwanatataq kunan p'unchaw munanki?"],
    [/^Idioma (cambiado a|sugerido:?) (.+)\. Puedes modificarlo en cualquier momento\.$/,"Rimay simi $2. Munaspa mayjt'ayta atinki."],
    [/^Región detectada: (.+)$/,"Suyu tarisqa: $1"],
    [/^Tienes (\d+) respuesta(?:s)? nueva(?:s)?$/,"$1 mushuq kutichiykuna kachkan"],
  ]:[
    [/^Hola, (.+)\. ¿Qué trámite necesitas hoy\?$/,"Kamisaraki, $1. ¿Kuna lurawsa jichhür munta?"],
    [/^Idioma (cambiado a|sugerido:?) (.+)\. Puedes modificarlo en cualquier momento\.$/,"Aru $2. Munasax mayjt'ayasma."],
    [/^Región detectada: (.+)$/,"Suyu jikxatasi: $1"],
    [/^Tienes (\d+) respuesta(?:s)? nueva(?:s)?$/,"$1 machaq kutichäwi utji"],
  ];
  for(const [pattern,replacement] of rules){if(pattern.test(text))return text.replace(pattern,replacement)}
  return text;
}

export function translateText(text,language){
  return translate(text,language);
}
